def count_missed_fogs(n, fogs):
    class Rectangle:
        def __init__(self, x1, x2, y1, y2):
            self.x1 = x1
            self.x2 = x2
            self.y1 = y1
            self.y2 = y2

        def area(self):
            return max(0, self.x2 - self.x1) * max(0, self.y2 - self.y1)

        def intersects(self, other):
            return not (self.x2 <= other.x1 or self.x1 >= other.x2 or
                        self.y2 <= other.y1 or self.y1 >= other.y2)

        def union(self, other):
            if not self.intersects(other):
                return [self, other]
            new_x1 = min(self.x1, other.x1)
            new_x2 = max(self.x2, other.x2)
            new_y1 = min(self.y1, other.y1)
            new_y2 = max(self.y2, other.y2)
            return [Rectangle(new_x1, new_x2, new_y1, new_y2)]

    class NetTracker:
        def __init__(self):
            self.nets = []

        def add_net(self, net):
            new_nets = [net]
            for existing_net in self.nets:
                temp_nets = []
                for new_net in new_nets:
                    if existing_net.intersects(new_net):
                        temp_nets.extend(existing_net.union(new_net))
                    else:
                        temp_nets.append(new_net)
                new_nets = temp_nets
            self.nets = new_nets

        def total_coverage(self):
            total_area = 0
            for net in self.nets:
                total_area += net.area()
            return total_area

    total_missed_fogs = 0
    fog_days = []

    for m_i, d_i, ell_i, r_i, h_i, delta_d_i, delta_x_i, delta_h_i in fogs:
        for k in range(m_i):
            fog_day = d_i + k * delta_d_i
            fog_x1 = ell_i + k * delta_x_i
            fog_x2 = r_i + k * delta_x_i
            fog_y1 = 0
            fog_y2 = h_i + k * delta_h_i
            fog_days.append((fog_day, Rectangle(fog_x1, fog_x2, fog_y1, fog_y2)))

    fog_days.sort()
    net_tracker = NetTracker()

    current_day = 0
    day_fogs = []

    for day, fog in fog_days:
        if day != current_day:
            missed_fogs = sum(1 for f in day_fogs if not any(net.intersects(f) for net in net_tracker.nets))
            total_missed_fogs += missed_fogs
            day_fogs = []
            current_day = day
        day_fogs.append(fog)

    missed_fogs = sum(1 for f in day_fogs if not any(net.intersects(f) for net in net_tracker.nets))
    total_missed_fogs += missed_fogs

    return total_missed_fogs

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
